// Room "P3 upper hall" (interior designer's part): the gambrel landing at the stair top. Box x55..57, y6..8, z14..20.
// The stair (x55, z15..18) and the doorway first cells (57,6,15), (57,6,19) and the window cells (55,14), (57,14) stay
// clear. Focal piece: a spruce coat rack on the north wall between the two windows, where the stair top looks.
// Supporting pieces: a fence-and-slab table with a candle in the south-west corner, a linen chest and a barrel dresser
// in the south-east, a stair bench on the west wall, a carpet runner up the lane. One standing lantern on the barrel
// lights the whole landing (no ceiling block is assumed above it).
import { layers, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { coatRack } from "../vocab.mjs";

export function build(g) {
  // the focal piece: coat rack on the north row, between the windows (x56, z14); banner faces the room (south)
  coatRack(g, { x: 56, y: 6, z: 14, facing: "south", color: "brown", wood: "spruce" });

  // furniture and lamps by layer. Rows run along +x (55..57), successive rows along +z (14..20). Spaces are left as found.
  layers(g, [55, 6, 14], {
    "r": "brown_carpet",                                    // runner up the middle lane
    "b": ["barrel", { facing: "up", open: "false" }],        // dresser in the south-east corner, lamp on its top
    "k": ["oak_stairs", { facing: "west", half: "bottom", shape: "straight" }], // bench, back to the west wall
    "T": "oak_fence",                                       // table leg
    "C": ["chest", { facing: "north", type: "single" }],    // linen chest by the table
  }, [
    [
      "...",   // z14: window cells x55 and x57 stay clear, coat rack (above) at x56
      " r.",   // z15: stair x55; doorway first cell x57 clear
      " r.",   // z16
      " r.",   // z17
      "...",   // z18: stair top landing (x55) clear
      "k..",   // z19: bench on x55; doorway first cell x57 clear
      ".TC",   // z20: table x56, chest x57
    ],
  ]);

  // the lamp on the barrel, and the table top (a top slab on the fence) with a candle; placed above the layer above
  layers(g, [55, 7, 14], {
    "L": ["lantern", { hanging: "false" }],                 // standing on the barrel top
    "S": ["oak_slab", { type: "top" }],                     // table top, sits on the fence post
  }, [
    [
      "...",
      "...",
      "...",
      "...",
      "..L",   // z18: lantern on the barrel at (57,7,18)
      "...",
      ".S.",   // z20: table top at (56,7,20)
    ],
  ]);

  // a lit candle on the table top, the second light in the south-west
  layers(g, [55, 8, 14], {
    "c": ["candle", { candles: "2", lit: "true" }],
  }, [
    [
      "...",
      "...",
      "...",
      "...",
      "...",
      "...",
      ".c.",   // z20: candle on the table top at (56,8,20)
    ],
  ]);
}

